style.css:
@-moz-document domain("youtube.com") {
ytd-topbar-logo-renderer #logo-icon {
        display: block !important;
        width: 120px !important;
        height: 42px !important;

        background: url("https://cdn.imageurlgenerator.com/uploads/478854c2-0d9f-49f2-b263-aafea1dab954.gif")
            center 3px / 74px auto no-repeat !important;
    }

    ytd-topbar-logo-renderer #logo-icon svg,
    ytd-topbar-logo-renderer #logo-icon yt-icon {
        display: none !important;
    }
}
